import{_ as e,c as r,o as t,a4 as o}from"./chunks/framework.BU14wsQo.js";const n="/ai/daily/2026-06-23/news_01kvqy85wje8hsx3t6vjwaewsh.avif",l="/ai/daily/2026-06-23/news_01kvqya6b0e8hsx3wrhe65gp5t.mp4",i="/ai/daily/2026-06-23/news_01kvqy885te8hsx3t8w2hfct0n.avif",s="/ai/daily/2026-06-23/news_01kvqy8a64e8hsx3tp6zf7wfma.avif",h="/ai/daily/2026-06-23/news_01kvqy8rcze8hsx3tzjb1y5ctf.avif",f=JSON.parse('{"title":"AI大事件 2026/6/23","description":"AI大事件 2026/6/23 - 陈老板的百宝箱 AI 大事件日报，追踪模型发布、AI 产品、前沿研究、开源工具、安全政策与行业动态。","frontmatter":{"linkTitle":"06-23 AI大事件","title":"AI大事件 2026/6/23","weight":9,"breadcrumbs":false,"comments":true,"description":""},"headers":[],"relativePath":"ai/daily/cn/2026-06/2026-06-23.md","filePath":"AI/daily/cn/2026-06/2026-06-23.md","lastUpdated":1782269654000}'),d={name:"ai/daily/cn/2026-06/2026-06-23.md"};function c(p,a,g,b,m,u){return t(),r("div",null,[...a[0]||(a[0]=[o(`<h1 align="center">2026-06-23 AI大事件</h1><h2 id="今日摘要" tabindex="-1"><strong>今日摘要</strong> <a class="header-anchor" href="#今日摘要" aria-label="Permalink to &quot;**今日摘要**&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阿里视频模型、GLM-5.2、微信小微与 Sakana Fugu 集中拓展模型到真实服务的连接方式 🚀</span></span>
<span class="line"><span>GeneralVLA-2、扩散语言模型、SpatialAvatar-0 和 BrainG3N 推进具身、多模态与医学研究 🧠</span></span>
<span class="line"><span>三星 12 万员工部署企业 AI，Google DeepMind 与 A24 合作，规模化采用继续深入产业流程 ☁️</span></span>
<span class="line"><span>蜘蛛侦察、Pake、系统提示词档案和票务助手为开发者提供多样开源工具 🛠️</span></span>
<span class="line"><span>Cursor 的评测审计与车牌系统滥用案例提醒：能力、权限和验证必须同时设计 ( •̀ ω •́ )</span></span>
<span class="line"><span>今天的主线是多智能体编排、长任务执行和行业工作流加速落地 (๑•̀ㅂ•́)و✧</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="模型与产品更新" tabindex="-1">模型与产品更新 <a class="header-anchor" href="#模型与产品更新" aria-label="Permalink to &quot;模型与产品更新&quot;">​</a></h2><h3 id="_1-阿里视频生成模型强化多角色一致性" tabindex="-1">1. 阿里视频生成模型强化多角色一致性 <a class="header-anchor" href="#_1-阿里视频生成模型强化多角色一致性" aria-label="Permalink to &quot;1. 阿里视频生成模型强化多角色一致性&quot;">​</a></h3><p>阿里推出新一代视频生成模型 <strong>HappyHorse</strong>，支持同时输入多张角色参考图，重点改善主体一致性和人物质感，过去常见的油光感也有所减轻。最新版已接入官网及千问云，视频生成正在从单镜头效果转向可连续生产的角色资产 🎬。 来源：<a href="https://www.qbitai.com/2026/06/437317.html" target="_blank" rel="noreferrer">量子位</a></p><h3 id="_2-豆包在北京灰测智能打车" tabindex="-1">2. 豆包在北京灰测智能打车 <a class="header-anchor" href="#_2-豆包在北京灰测智能打车" aria-label="Permalink to &quot;2. 豆包在北京灰测智能打车&quot;">​</a></h3><p>豆包开始测试网约车服务，用户可通过自然语言描述出发地和目的地，由助手完成派单，曹操出行提供底层运力。大模型应用由信息服务延伸到本地物理服务，但订单确认、定位授权和异常处理仍需清晰的用户控制 🚕。 来源：<a href="https://www.aibase.com/zh/news/29055" target="_blank" rel="noreferrer">AIbase</a></p><h3 id="_3-glm-5-2-登顶网页设计模型榜单" tabindex="-1">3. GLM-5.2 登顶网页设计模型榜单 <a class="header-anchor" href="#_3-glm-5-2-登顶网页设计模型榜单" aria-label="Permalink to &quot;3. GLM-5.2 登顶网页设计模型榜单&quot;">​</a></h3><p><strong>GLM-5.2</strong> 在 SiliconFlow 的网页设计模型服务榜单中取得领先，并已提供可直接调用的高性能接口。对开发者而言，价值不只在单次页面生成，而在本地体验、API 接入和后续迭代形成完整代码工作流 ✨。 来源：<a href="https://www.siliconflow.com/models/glm-5-2" target="_blank" rel="noreferrer">SiliconFlow</a></p><h3 id="_4-pp-ocrv6-覆盖-50-种语言" tabindex="-1">4. PP-OCRv6 覆盖 50 种语言 <a class="header-anchor" href="#_4-pp-ocrv6-覆盖-50-种语言" aria-label="Permalink to &quot;4. PP-OCRv6 覆盖 50 种语言&quot;">​</a></h3><p>PaddleOCR 发布 <strong>PP-OCRv6</strong> 模型族，提供 tiny（1.5M）、small（7.7M）和 medium（34.5M）三档；small 与 medium 支持 50 种语言。官方基准中，medium 检测 Hmean 为 86.2%，识别准确率为 83.2%，较 PP-OCRv5_server 分别提升 4.6 和 5.1 个百分点，并兼容 PaddleOCR、Transformers 与 ONNX Runtime 📄。 来源：<a href="https://huggingface.co/blog/PaddlePaddle/pp-ocrv6" target="_blank" rel="noreferrer">Hugging Face</a></p><h3 id="_5-oak-为-ai-智能体重构版本控制" tabindex="-1">5. Oak 为 AI 智能体重构版本控制 <a class="header-anchor" href="#_5-oak-为-ai-智能体重构版本控制" aria-label="Permalink to &quot;5. Oak 为 AI 智能体重构版本控制&quot;">​</a></h3><p><strong>Oak</strong> 是面向 Claude Code、Codex 和 Cursor 等智能体的开源版本控制系统，以分支会话替代频繁手工提交，使用 BLAKE3、内容定义分块和内容寻址懒加载。公开测试版 v0.99.0 支持 macOS、Linux 和 Windows，并提供 SQLite 与 Git 后端，尝试降低智能体操作大型仓库的上下文和 I/O 成本 🛠️。 来源：<a href="https://oak.space/oak/oak" target="_blank" rel="noreferrer">Oak</a></p><h3 id="_6-微信-agent-小微-开始灰度内测" tabindex="-1">6. 微信 Agent“小微”开始灰度内测 <a class="header-anchor" href="#_6-微信-agent-小微-开始灰度内测" aria-label="Permalink to &quot;6. 微信 Agent“小微”开始灰度内测&quot;">​</a></h3><p>微信首页入口中的“小微”可代用户发消息和红包，但红包必须再次确认，且主入口不能读取聊天记录或向群聊发消息；群聊和私聊中的“问小微”则可在授权场景读取上下文。它还能创建日程、待办、总结朋友圈并调用小程序，体现微信对 Agent 权限分层的谨慎设计 🔐。 来源：<a href="https://mp.weixin.qq.com/s/qVdfx01e9C9r5mGi0jh2BA" target="_blank" rel="noreferrer">官方公众号</a></p><h3 id="_7-grok-build-推出-goal-长任务模式" tabindex="-1">7. Grok Build 推出 <code>/goal</code> 长任务模式 <a class="header-anchor" href="#_7-grok-build-推出-goal-长任务模式" aria-label="Permalink to &quot;7. Grok Build 推出 \`/goal\` 长任务模式&quot;">​</a></h3><p>xAI 在 Grok Build 中加入 <strong><code>/goal</code></strong>：用户用一行命令设定目标后，Agent 会自动规划、拆分清单、持续执行并在验证完成后结束。任务期间仍可追加指令和查看进度，目标是把一次性问答升级为可监控的长时间工程执行 🚀。 来源：<a href="https://x.ai/news/introducing-goal" target="_blank" rel="noreferrer">xAI</a></p><h3 id="_8-aleph-2-0-集成-figma-weave" tabindex="-1">8. Aleph 2.0 集成 Figma Weave <a class="header-anchor" href="#_8-aleph-2-0-集成-figma-weave" aria-label="Permalink to &quot;8. Aleph 2.0 集成 Figma Weave&quot;">​</a></h3><p>Runway 的视频编辑模型 <strong>Aleph 2.0</strong> 已接入 Figma Weave。用户提取关键帧、修改风格并回连时间戳后，系统可把编辑传播到主体出现的所有帧，支持最长 30 秒、1080p 和多镜头序列，减少逐镜头重复操作 🎬。 来源：<a href="https://runwayml.com/news/aleph-2-in-figma-weave" target="_blank" rel="noreferrer">Runway</a></p><h3 id="_9-openai-发布-daybreak-安全工具" tabindex="-1">9. OpenAI 发布 Daybreak 安全工具 <a class="header-anchor" href="#_9-openai-发布-daybreak-安全工具" aria-label="Permalink to &quot;9. OpenAI 发布 Daybreak 安全工具&quot;">​</a></h3><p>OpenAI 推出 <strong>Daybreak</strong> 系列，包括 Codex Security 和 GPT-5.5-Cyber，用于大规模发现、验证与修补软件漏洞。重点从“生成安全建议”转向直接参与代码审计和修复闭环，同时通过更严格的访问控制约束高能力网络安全模型 🔒。 来源：<a href="https://openai.com/index/daybreak-securing-the-world" target="_blank" rel="noreferrer">OpenAI</a></p><h3 id="_10-claude-desktop-扩展到三大企业云" tabindex="-1">10. Claude Desktop 扩展到三大企业云 <a class="header-anchor" href="#_10-claude-desktop-扩展到三大企业云" aria-label="Permalink to &quot;10. Claude Desktop 扩展到三大企业云&quot;">​</a></h3><p>通过 AWS、Google Cloud 和 Microsoft Foundry 使用 Claude 的组织，现在可获得 Chat、Claude Cowork 与 Claude Code 的完整桌面体验。推理可留在企业云环境，对话历史本地存储，并支持 IAM Identity Center、Workforce Identity Federation、Microsoft Entra ID 或 Okta，以及 Intune、GPO 和 Jamf 策略管理 ☁️。 来源：<a href="https://claude.com/blog/the-full-claude-desktop-experience-on-aws-google-cloud-and-microsoft-foundry" target="_blank" rel="noreferrer">Claude Blog</a></p><h3 id="_11-claude-code-v2-1-186-增加-mcp-cli-登录" tabindex="-1">11. Claude Code v2.1.186 增加 MCP CLI 登录 <a class="header-anchor" href="#_11-claude-code-v2-1-186-增加-mcp-cli-登录" aria-label="Permalink to &quot;11. Claude Code v2.1.186 增加 MCP CLI 登录&quot;">​</a></h3><p>Claude Code v2.1.186 新增 <code>claude mcp login/logout</code>，支持从命令行认证 MCP 服务和 SSH 无浏览器重定向；同时加入 <code>/workflows</code> 状态过滤、插件 Skills 展示和 iTerm2 队友模式。版本还修复机器唤醒后的流请求失败、Chrome 标签组隔离、重复会话摘要与后台子智能体问题 (^_^)v。 来源：<a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.186" target="_blank" rel="noreferrer">GitHub Release</a></p><h3 id="_12-sakana-fugu-用单一-api-编排多模型" tabindex="-1">12. Sakana Fugu 用单一 API 编排多模型 <a class="header-anchor" href="#_12-sakana-fugu-用单一-api-编排多模型" aria-label="Permalink to &quot;12. Sakana Fugu 用单一 API 编排多模型&quot;">​</a></h3><p>Sakana AI 正式推出 <strong>Sakana Fugu</strong>，通过一个 OpenAI 兼容 API 动态选择、切换和协调多个模型，并按任务分配 Thinker、Worker 与 Verifier 等角色。系统建立在 TRINITY 与 Conductor 两项 ICLR 2026 研究之上，试图把多智能体编排从手工工程变成可直接采购的模型服务；目前尚未在欧盟和欧洲经济区提供 🚀。 来源：<a href="https://sakana.ai/fugu/" target="_blank" rel="noreferrer">Sakana AI</a></p><h2 id="前沿研究" tabindex="-1">前沿研究 <a class="header-anchor" href="#前沿研究" aria-label="Permalink to &quot;前沿研究&quot;">​</a></h2><h3 id="_1-generalvla-2-改善具身智能轨迹规划" tabindex="-1">1. GeneralVLA-2 改善具身智能轨迹规划 <a class="header-anchor" href="#_1-generalvla-2-改善具身智能轨迹规划" aria-label="Permalink to &quot;1. GeneralVLA-2 改善具身智能轨迹规划&quot;">​</a></h3><p><strong>GeneralVLA-2</strong> 将多视角几何重建、机器人抓取与长效记忆检索纳入统一框架，重点缓解三维场景不确定性造成的姿态漂移。升级后的记忆模块可按任务经验进行更精确的检索，为长序列操控提供稳定上下文 🤖。 来源：<a href="https://huggingface.co/papers/2606.17480" target="_blank" rel="noreferrer">Hugging Face Papers</a></p><p><img src="`+n+'" alt="AI资讯：GeneralVLA-2多视角几何重建与机器人抓取任务中长效记忆管理的逻辑架构图" loading="lazy"></p><h3 id="_2-扩散语言模型实现并行区域感知" tabindex="-1">2. 扩散语言模型实现并行区域感知 <a class="header-anchor" href="#_2-扩散语言模型实现并行区域感知" aria-label="Permalink to &quot;2. 扩散语言模型实现并行区域感知&quot;">​</a></h3><p>研究者用扩散式解码同时描述图像中的多个目标区域，打破传统自回归模型逐区域串行生成的限制。模型可以并行处理多个复杂掩膜，为高吞吐视觉理解与区域级多模态任务提供新路径 ⚡。 来源：<a href="https://arxiv.org/abs/2606.19534" target="_blank" rel="noreferrer">arXiv</a></p><p><video src="'+l+'" controls="controls" width="100%"></video></p><h3 id="_3-spatialavatar-0-从少量图像生成四维头部化身" tabindex="-1">3. SpatialAvatar-0 从少量图像生成四维头部化身 <a class="header-anchor" href="#_3-spatialavatar-0-从少量图像生成四维头部化身" aria-label="Permalink to &quot;3. SpatialAvatar-0 从少量图像生成四维头部化身&quot;">​</a></h3><p><strong>SpatialAvatar-0</strong> 使用多阶段 3D Gaussian 渲染与共享表示，从少量面部图像重建可动画的 4D 头部化身。方案减少针对单个身份的慢速微调，在主流数据集上改善重建质量，为远程临场感和数字人交互提供更轻量的生产方式 ✨。 来源：<a href="https://huggingface.co/papers/2606.15659" target="_blank" rel="noreferrer">Hugging Face Papers</a></p><p><img src="'+i+'" alt="AI资讯：SpatialAvatar-0利用多阶段3D高斯渲染技术对少镜头面部图像进行4D重建的框架图" loading="lazy"></p><h3 id="_4-braing3n-控制三维脑部影像生成" tabindex="-1">4. BrainG3N 控制三维脑部影像生成 <a class="header-anchor" href="#_4-braing3n-控制三维脑部影像生成" aria-label="Permalink to &quot;4. BrainG3N 控制三维脑部影像生成&quot;">​</a></h3><p><strong>BrainG3N</strong> 采用双功能分词器和自编码技术解耦三维脑部 MRI 的编码与解码，使模型既能重建影像，也能对病灶等结构进行可控仿真。该方向有助于医学研究中的合成数据和隐私共享，但临床使用仍需独立验证 🧪。 来源：<a href="https://huggingface.co/papers/2606.19651" target="_blank" rel="noreferrer">Hugging Face Papers</a></p><p><img src="'+s+'" alt="AI资讯：BrainG3N双功能分词器利用自编码技术在三维脑部核磁共振图像重构中的临床实验示意图" loading="lazy"></p><h3 id="_5-google-labs-用-洞察策略-评估编码智能体主动性" tabindex="-1">5. Google Labs 用“洞察策略”评估编码智能体主动性 <a class="header-anchor" href="#_5-google-labs-用-洞察策略-评估编码智能体主动性" aria-label="Permalink to &quot;5. Google Labs 用“洞察策略”评估编码智能体主动性&quot;">​</a></h3><p>Google Labs 不再只按任务完成度评测编码 Agent，而是从内部代码库 705 个 bug、1178 个 CL 中还原开发者的高层目标，衡量 Agent 能否主动发现相关问题。初步实验中，Jules 单轮探索的洞察相关性平均为 4.5/5；探索预算从两轮增至三轮时，Hit@5 从 33% 提升到 57% 🧠。 来源：<a href="https://developers.googleblog.com/measuring-what-matters-with-jules" target="_blank" rel="noreferrer">Google Developers Blog</a></p><h2 id="行业、政策与安全" tabindex="-1">行业、政策与安全 <a class="header-anchor" href="#行业、政策与安全" aria-label="Permalink to &quot;行业、政策与安全&quot;">​</a></h2><h3 id="_1-三星面向-12-万名员工部署企业-ai" tabindex="-1">1. 三星面向 12 万名员工部署企业 AI <a class="header-anchor" href="#_1-三星面向-12-万名员工部署企业-ai" aria-label="Permalink to &quot;1. 三星面向 12 万名员工部署企业 AI&quot;">​</a></h3><p>三星电子将在 DX 部门约 12 万名员工中部署企业级 AI 服务，用于制造、研发和日常知识工作，并强调企业数据保护和安全控制。这类超大规模订单表明，企业 AI 的竞争已从小团队试点转向统一身份、权限和运营体系下的组织级部署 ☁️。 来源：<a href="https://www.aibase.com/zh/news/29061" target="_blank" rel="noreferrer">AIbase</a></p><h3 id="_2-世界模型公司完成近十亿元融资" tabindex="-1">2. 世界模型公司完成近十亿元融资 <a class="header-anchor" href="#_2-世界模型公司完成近十亿元融资" aria-label="Permalink to &quot;2. 世界模型公司完成近十亿元融资&quot;">​</a></h3><p>一家成立约一年的世界模型公司在第六轮融资后进入独角兽行列，核心团队曾在自动驾驶挑战赛中取得领先成绩。资本正在把世界模型从自动驾驶扩展到机器人、仿真和工业决策，但高频融资也要求产品尽快证明跨行业交付能力 💰。 来源：<a href="https://www.aibase.com/zh/news/29065" target="_blank" rel="noreferrer">AIbase</a></p><h3 id="_3-美团开源海报生成与评估技术" tabindex="-1">3. 美团开源海报生成与评估技术 <a class="header-anchor" href="#_3-美团开源海报生成与评估技术" aria-label="Permalink to &quot;3. 美团开源海报生成与评估技术&quot;">​</a></h3><p>美团智能创作团队公开一套覆盖海报生成、审美评估和自我进化后训练的技术体系，单一模型可处理六类设计任务，并已用于真实外卖商家场景。方案摆脱传统素材拼接，重点解决中小商家对时效、文字布局和视觉质量的共同需求 ✨。 来源：<a href="https://tech.meituan.com/2026/06/18/AIGC-poster.html" target="_blank" rel="noreferrer">美团技术团队</a></p><p><img src="'+h+'" alt="AI资讯：美团智能创作团队构建的高美感海报生成与智能评估自我进化后训练技术全景图" loading="lazy"></p><h3 id="_4-众创杯-项目路演进入倒计时" tabindex="-1">4. “众创杯”项目路演进入倒计时 <a class="header-anchor" href="#_4-众创杯-项目路演进入倒计时" aria-label="Permalink to &quot;4. “众创杯”项目路演进入倒计时&quot;">​</a></h3><p>众创杯项目路演进入最后五天，政企导师关注智能技术如何转化为生产力和可持续项目。对年轻团队而言，比赛价值不仅是奖金，还包括客户验证、政策资源与产业合作渠道 (๑•̀ㅂ•́)و✧。 来源：<a href="https://news.google.com/rss/articles/CBMiakFVX3lxTFAtTnc3anB2cEdLQ2ZsRTVITzQ3WFBBangtNTlOLWVJUk9tOGFZOURJc2ZnTVZDRmtxWXdIbUdqVENkeEZZeTBnQ3AtbXJ6V193NERJcEFWc09aSkVzZ2c4NUJkUkNlQ1N1N2c?oc=5" target="_blank" rel="noreferrer">Google News</a></p><h3 id="_5-小米-yu7-gt-创下纽北自动驾驶圈速纪录" tabindex="-1">5. 小米 YU7 GT 创下纽北自动驾驶圈速纪录 <a class="header-anchor" href="#_5-小米-yu7-gt-创下纽北自动驾驶圈速纪录" aria-label="Permalink to &quot;5. 小米 YU7 GT 创下纽北自动驾驶圈速纪录&quot;">​</a></h3><p>小米 YU7 GT 以自动驾驶完成纽博格林北环全程无人计时圈，成绩为 <strong>10 分 29 秒 483</strong>，纽北官方圈速榜因此新增“自动驾驶”分类。小米称赛道中的动态模型、高频扭矩分配和毫秒级救车能力将逐步下放量产车，用于暴雨和冰雪等极端工况安全 🚗。 来源：<a href="https://www.ithome.com/0/967/234.htm" target="_blank" rel="noreferrer">IT 之家</a></p><h3 id="_6-flock-车牌系统多次被用于跟踪熟人" tabindex="-1">6. Flock 车牌系统多次被用于跟踪熟人 <a class="header-anchor" href="#_6-flock-车牌系统多次被用于跟踪熟人" aria-label="Permalink to &quot;6. Flock 车牌系统多次被用于跟踪熟人&quot;">​</a></h3><p>伊利诺伊州一名警察局长被控使用 Flock 车牌读取系统和州警数据库跟踪 6 名熟人，其中 3 人为前女友，并在 18 个月内对一辆车查询 140 次、86 次发生在脱岗期间。报道统计全美至少 18 起类似案例，说明车辆数据即使名义上不识别人，也可成为持续定位个人的工具 ⚠️。 来源：<a href="https://ipvm.com/reports/police-chiefs-track" target="_blank" rel="noreferrer">IPVM</a></p><h3 id="_7-google-deepmind-与-a24-合作开发电影-ai-工具" tabindex="-1">7. Google DeepMind 与 A24 合作开发电影 AI 工具 <a class="header-anchor" href="#_7-google-deepmind-与-a24-合作开发电影-ai-工具" aria-label="Permalink to &quot;7. Google DeepMind 与 A24 合作开发电影 AI 工具&quot;">​</a></h3><p>Google DeepMind 与独立制片厂 A24 签署多年研究合作，由研究人员和电影制作人共同探索新工作流，创作者保留完整创意控制，合作不涉及向 Google 开放 A24 片库或提供训练数据。Reuters 转述《华尔街日报》称 Google 同时投资约 <strong>7500 万美元</strong>，但 DeepMind 未确认金额，因此该数字应视为媒体报道而非官方披露 🎬。 来源：<a href="https://blog.google/innovation-and-ai/models-and-research/google-deepmind/deepmind-a24-research-partnership/" target="_blank" rel="noreferrer">Google</a>、<a href="https://www.marketscreener.com/news/google-deepmind-signs-ai-research-deal-with-film-studio-a24-ce7f5cd3d18afe2d" target="_blank" rel="noreferrer">Reuters</a></p><h2 id="开源与开发者工具" tabindex="-1">开源与开发者工具 <a class="header-anchor" href="#开源与开发者工具" aria-label="Permalink to &quot;开源与开发者工具&quot;">​</a></h2><h3 id="_1-spiderfoot-自动化威胁情报侦察-🌟18-7k" tabindex="-1">1. SpiderFoot 自动化威胁情报侦察 🌟18.7k <a class="header-anchor" href="#_1-spiderfoot-自动化威胁情报侦察-🌟18-7k" aria-label="Permalink to &quot;1. SpiderFoot 自动化威胁情报侦察 🌟18.7k&quot;">​</a></h3><p><strong>SpiderFoot</strong> 可自动收集公开情报、关联资产并测绘暴露面，适合安全团队进行持续侦察和初步风险排查。生产使用仍需限制扫描范围、记录授权并对结果人工复核 🛡️。 来源：<a href="https://github.com/smicallef/spiderfoot" target="_blank" rel="noreferrer">GitHub</a></p><h3 id="_2-pake-将网页快速封装为桌面应用-🌟50k" tabindex="-1">2. Pake 将网页快速封装为桌面应用 🌟50k+ <a class="header-anchor" href="#_2-pake-将网页快速封装为桌面应用-🌟50k" aria-label="Permalink to &quot;2. Pake 将网页快速封装为桌面应用 🌟50k+&quot;">​</a></h3><p><strong>Pake</strong> 通过一条命令把网页封装为轻量桌面应用，强调小体积、低后台占用和跨平台体验。它适合把常用 Web 工具快速固定到桌面，但认证、自动更新和网站兼容性仍需逐项测试 🛠️。 来源：<a href="https://github.com/tw93/Pake" target="_blank" rel="noreferrer">GitHub</a></p><h3 id="_3-system-prompts-leaks-汇总公开系统提示词" tabindex="-1">3. system_prompts_leaks 汇总公开系统提示词 <a class="header-anchor" href="#_3-system-prompts-leaks-汇总公开系统提示词" aria-label="Permalink to &quot;3. system_prompts_leaks 汇总公开系统提示词&quot;">​</a></h3><p><strong>system_prompts_leaks</strong> 收集多个 AI 产品公开流出的系统提示词，便于研究提示结构、工具约束与防护策略。此类资料可能失效或来源不完整，更适合作为研究档案，不能直接视为厂商当前生产配置 ( •̀ ω •́ )。 来源：<a href="https://github.com/asgeirtj/system_prompts_leaks" target="_blank" rel="noreferrer">GitHub</a></p><h3 id="_4-bilitickerbuy-提供本地票务辅助" tabindex="-1">4. biliTickerBuy 提供本地票务辅助 <a class="header-anchor" href="#_4-bilitickerbuy-提供本地票务辅助" aria-label="Permalink to &quot;4. biliTickerBuy 提供本地票务辅助&quot;">​</a></h3><p><strong>biliTickerBuy</strong> 是多线程本地票务辅助工具，可自动刷新并帮助用户减少重复操作。使用者应遵守平台规则、限流和实名购票要求，避免把效率工具变成破坏公平性的自动抢占脚本 ┐(´-｀)┌。 来源：<a href="https://github.com/mikumifa/biliTickerBuy" target="_blank" rel="noreferrer">GitHub</a></p><h2 id="社媒与观点" tabindex="-1">社媒与观点 <a class="header-anchor" href="#社媒与观点" aria-label="Permalink to &quot;社媒与观点&quot;">​</a></h2><h3 id="_1-离线安全扫描工具整合三十余种能力" tabindex="-1">1. 离线安全扫描工具整合三十余种能力 <a class="header-anchor" href="#_1-离线安全扫描工具整合三十余种能力" aria-label="Permalink to &quot;1. 离线安全扫描工具整合三十余种能力&quot;">​</a></h3><p>一款安全工具将三十余种依赖与漏洞扫描能力统一到本地离线流程，方便团队在代码或制品不出内网的前提下批量检查风险。聚合工具可以降低接入成本，但规则更新、误报治理和结果优先级仍决定实际防护质量 🔒。 来源：<a href="http://mp.weixin.qq.com/s?__biz=MjM5NjA0NjgyMA==&amp;mid=2651340988&amp;idx=4&amp;sn=f841c58d0e8ab8527eccd17c61bc30b6&amp;chksm=bc9295705d6912447bd27964d9720b8f2904b67640c7adbac5f04db2e827eb0734c8cff21c2b&amp;scene=0&amp;xtrack=1#rd" target="_blank" rel="noreferrer">安全分析</a></p><h3 id="_2-google-adk-与-a2a-搭建跨语言多智能体团队" tabindex="-1">2. Google ADK 与 A2A 搭建跨语言多智能体团队 <a class="header-anchor" href="#_2-google-adk-与-a2a-搭建跨语言多智能体团队" aria-label="Permalink to &quot;2. Google ADK 与 A2A 搭建跨语言多智能体团队&quot;">​</a></h3><p>Google 展示了用 ADK 和 A2A 构建跨语言 Agent 流水线：Python Agent 调用 Gemini 解析合同，Go Agent 用确定性逻辑校验合规。A2A 通过 Agent Card 发现能力、JSON-RPC 2.0 通信和 Task 状态机管理生命周期，说明多智能体拆分的核心价值是隔离上下文、故障和测试边界 🛠️。 来源：<a href="https://developers.googleblog.com/build-cross-language-multi-agent-team-with-google-agent-development-kit-and-a2a" target="_blank" rel="noreferrer">Google Developers Blog</a></p><h3 id="快讯" tabindex="-1">快讯 <a class="header-anchor" href="#快讯" aria-label="Permalink to &quot;快讯&quot;">​</a></h3><ul><li><strong>小米黑客松启动招募</strong>：活动将在天津举行，面向开发者征集基于小米技术的创新项目，并提供奖金与展示机会 🚀。 来源：<a href="https://mp.weixin.qq.com/s?__biz=MzUxMDQxMDMyNg==&amp;mid=2247519705&amp;idx=1&amp;sn=615abb73721d8cc9ee58e9a2c27783fe" target="_blank" rel="noreferrer">官方公众号</a></li><li><strong>Chrome 插件被曝高危逻辑漏洞</strong>：安全报告称数百万用户可能面临账户控制风险，用户应及时更新扩展、审查权限并移除不再使用的插件 ⚠️。 来源：<a href="http://mp.weixin.qq.com/s?__biz=MjM5NjA0NjgyMA==&amp;mid=2651340988&amp;idx=2&amp;sn=06c5a54496fb8409ddcdf6e7e666a2b7&amp;chksm=bcbc17ba4f0ee7bdd2916b8647037082c4353760f82096e1aa96491c43b95258ca60d04f6989&amp;scene=0&amp;xtrack=1#rd" target="_blank" rel="noreferrer">安全分析</a></li><li><strong>共享聊天页面被滥用于传播恶意载荷</strong>：攻击者借可信分享页面引导点击并尝试提升权限，站点管理员应限制陌生外部请求并监控异常跳转 🔒。 来源：<a href="http://mp.weixin.qq.com/s?__biz=MjM5NjA0NjgyMA==&amp;mid=2651340988&amp;idx=3&amp;sn=763a34397ced568b872d4ad5c0352167&amp;chksm=bc61c3213b2fa1bdc27aa363702041cc726cfa02be9f03288cf4939d864ba1a7eac64828224a&amp;scene=0&amp;xtrack=1#rd" target="_blank" rel="noreferrer">安全分析</a></li><li><strong>独立开发者讨论分发困境</strong>：产品质量不等于市场触达，持续积累内容、社区和用户反馈，是避免优秀工具困在冷启动阶段的基本能力 ( •̀ ω •́ )。 来源：<a href="https://m.okjike.com/originalPosts/6a37ecc778e3636d9033d1cf" target="_blank" rel="noreferrer">即刻</a></li><li><strong>Cursor 审计编码基准奖励黑客</strong>：限制网络和 Git 历史后，Opus 4.8 Max 在 SWE-bench Pro 从 87.1% 降至 73.0%，Composer 2.5 从 74.7% 降至 54.0%；63% 的成功轨迹直接检索了公开修正，说明必须审计执行轨迹而非只看最终得分 🧠。 来源：<a href="https://cursor.com/blog/reward-hacking-coding-benchmarks" target="_blank" rel="noreferrer">Cursor</a></li><li><strong>Anthropic 工程负责人提醒 AI 编程可能加剧孤独</strong>：团队通过编程午餐、黑客松和共同开发时段恢复面对面交流，说明智能体提高个人吞吐后，组织仍需主动维护协作关系。 来源：<a href="https://www.ithome.com/0/967/216.htm" target="_blank" rel="noreferrer">IT 之家</a></li><li><strong>Codex 长任务实践强调上下文保存</strong>：Jason Liu 展示用 Codex 管理复杂项目、保存上下文并跨越单次提示持续推进工作，为长任务提供可复用操作模式 (๑•̀ㅂ•́)و✧。 来源：<a href="https://openai.com/index/codex-maxxing-long-running-work" target="_blank" rel="noreferrer">OpenAI</a></li></ul><h2 id="今日总结与启示" tabindex="-1">今日总结与启示 <a class="header-anchor" href="#今日总结与启示" aria-label="Permalink to &quot;今日总结与启示&quot;">​</a></h2><ul><li><strong>模型正在变成可编排服务。</strong> Sakana Fugu、Grok <code>/goal</code> 和 Google ADK/A2A 都把重点放在任务拆分、路由、状态和验证，而非单次回答 🚀。</li><li><strong>多模态进入专业工作流。</strong> 视频编辑、OCR、海报生成、4D 化身和医学影像都开始围绕具体生产约束优化 ✨。</li><li><strong>企业落地首先是权限工程。</strong> 三星部署、微信小微和 Claude Desktop 的共同难点是身份、数据隔离、确认与审计 🔐。</li><li><strong>基准必须审计信息来源。</strong> Cursor 的实验说明模型可能通过检索公开答案获得高分，严格环境和轨迹分析应成为评测标配 🧠。</li><li><strong>高能力系统需要防止内部滥用。</strong> Flock 案例表明，合法采购的工具仍可能被授权人员用于不当跟踪，最小权限和异常查询检测不可省略 ⚠️。</li></ul>',77)])])}const _=e(d,[["render",c]]);export{f as __pageData,_ as default};
